#!/bin/bash
# build-arm64.sh [errors] [files]: build /bo1/p32tree (generated by build-p32.sh) for AArch64 Linux, cross-compiled
# inside the bo1-x64 container against the sysroot /bo1/arm64root. Run with qemu-aarch64-static -L /bo1/arm64root.
cd /bo1/p32tree || exit 1
R=/bo1/arm64root
B=build/arm64; mkdir -p build
T="--target=aarch64-linux-gnu --sysroot=$R"
[ -f $B/build.ninja ] || cmake -S . -B $B -G Ninja -DBO1_NATIVE=ON -DBO1_NATIVE_ARCH=arm64 \
  -DCMAKE_SYSTEM_NAME=Linux -DCMAKE_SYSTEM_PROCESSOR=aarch64 -DCMAKE_SYSROOT=$R \
  -DCMAKE_C_COMPILER=/bo1/llvm/build/bin/clang -DCMAKE_CXX_COMPILER=/bo1/llvm/build/bin/clang++ \
  -DCMAKE_C_COMPILER_TARGET=aarch64-linux-gnu -DCMAKE_CXX_COMPILER_TARGET=aarch64-linux-gnu \
  -DCMAKE_FIND_ROOT_PATH=$R -DCMAKE_FIND_ROOT_PATH_MODE_LIBRARY=ONLY -DCMAKE_FIND_ROOT_PATH_MODE_INCLUDE=ONLY -DCMAKE_FIND_ROOT_PATH_MODE_PACKAGE=ONLY -DCMAKE_FIND_ROOT_PATH_MODE_PROGRAM=NEVER \
  "-DCMAKE_CXX_FLAGS=-nostdinc++ -isystem /usr/lib/llvm-21/include/c++/v1" \
  "-DCMAKE_EXE_LINKER_FLAGS=-fuse-ld=lld -L$R/usr/lib/llvm-21/lib -Wl,-rpath,/usr/lib/llvm-21/lib" \
  "-DCMAKE_CXX_STANDARD_LIBRARIES=-lc++abi" -DCMAKE_BUILD_TYPE=${BUILD_TYPE:-Release} > $B.configure.log 2>&1 || { tail -30 $B.configure.log; exit 1; }
nice -n 19 ionice -c3 ninja -C $B -j ${JOBS:-6} -k 0 > $B/build.log 2>&1
echo "ninja exit=$?  failed TUs: $(grep -c "^FAILED" $B/build.log)  errors: $(grep -c "error:" $B/build.log)"
grep -E "error:" $B/build.log | sed -E "s/^[^ ]+: //" | sed -E "s/'[^']*'/'X'/g" | sort | uniq -c | sort -rn | head -${1:-40}
echo "--- by file"
grep -E "error:" $B/build.log | cut -d: -f1 | sed "s#/bo1/p32tree/##" | sort | uniq -c | sort -rn | head -${2:-25}
